/**
 * Golden tests for the generated files, from real pipeline outputs: the canonical spec
 * (`orderModel()`, byte-identical to examples/orders-app's spec) with the extractor's golden code
 * model of the clean orders app, and the B3 variant's code model and counterexamples
 * (`fixtures/b3-refund-race.json`). The generated files are executed against the real app by the
 * CLI's end-to-end suite (packages/cli/test/e2e/test-command.test.ts).
 */
import type { BehaviorModel, Finding, Trace } from "@tsverify/ir";
import { orderModel } from "@tsverify/ir/testing";
import { describe, expect, it } from "vitest";
import specTrace from "../../checker/test/__golden__/b6-refund-race.trace.json" with {
  type: "json",
};
import cleanCode from "../../extractor/test/__golden__/orders-app.code.json" with { type: "json" };
import { generate } from "../src/index";
import b3 from "./fixtures/b3-refund-race.json" with { type: "json" };

const OUT = ".tsverify/generated/order-lifecycle";
const SPEC_FILE = "src/orders/order.behavior.yaml";

function spec(): BehaviorModel {
  return { ...orderModel(), file: SPEC_FILE };
}

const clean = cleanCode as unknown as BehaviorModel;

describe("clean orders app: path, forbidden and guard tests", () => {
  const result = generate({ spec: spec(), code: clean, findings: [], outDir: OUT });

  it("writes one file per kind", () => {
    expect(result.files.map((f) => f.path)).toEqual([
      "paths.test.ts",
      "forbidden.test.ts",
      "guards.test.ts",
    ]);
  });

  it.each(["paths.test.ts", "forbidden.test.ts", "guards.test.ts"])("%s", async (path) => {
    const file = result.files.find((f) => f.path === path);
    await expect(file?.content).toMatchFileSnapshot(`__golden__/clean/${path}.txt`);
  });

  it("starts every file with the generated header naming the spec", () => {
    for (const f of result.files) {
      expect(f.content.split("\n").slice(0, 2)).toEqual([
        "// Generated by tsverify — do not edit. `tsverify test` deletes and rewrites this directory on every run.",
        `// Spec: ${SPEC_FILE} (behavior "Order lifecycle")`,
      ]);
    }
  });

  it("describes every test for the CLI", async () => {
    expect(result.tests.filter((t) => t.kind === "path")).toHaveLength(5);
    expect(result.tests.filter((t) => t.kind === "forbidden")).toHaveLength(25);
    expect(result.tests.filter((t) => t.kind === "guard")).toHaveLength(3);
    expect(result.tests.find((t) => t.name === "refund: paid → refunded (as admin)")).toEqual({
      file: "paths.test.ts",
      name: "refund: paid → refunded (as admin)",
      kind: "path",
      transition: "refund",
      from: "paid",
      actor: "admin",
      codeAt: { file: "src/orders/refund.ts", line: 17, column: 5, endLine: 17, endColumn: 30 },
    });
    await expect(`${JSON.stringify(result.tests, null, 2)}\n`).toMatchFileSnapshot(
      "__golden__/clean/tests.json.txt",
    );
  });

  it("explains the guard tests it cannot generate", () => {
    expect(result.skipped.map((f) => [f.id, f.severity])).toEqual([
      ["not-generated:Order lifecycle:testgen:guards:expire", "info"],
      ["not-generated:Order lifecycle:testgen:guards:payment_succeeded", "info"],
    ]);
  });

  it("is deterministic", () => {
    const again = generate({ spec: spec(), code: clean, findings: [], outDir: OUT });
    expect(again).toEqual(result);
  });
});

describe("by lists alternatives: guard tests per listed actor", () => {
  /** `ship` by admin or customer (owner); `refund` by admin or system (no fixture). */
  function alternatives(): BehaviorModel {
    const model = spec();
    for (const t of model.transitions) {
      if (t.name === "ship") t.by = ["admin", "customer"];
      if (t.name === "refund") t.by = ["admin", "system"];
    }
    const customer = model.actors.customer;
    if (customer) customer.requires = [{ name: "owner", args: [], raw: "owner" }];
    return model;
  }
  const result = generate({ spec: alternatives(), code: clean, findings: [], outDir: OUT });

  it("tests each other listed actor on its own, and actors outside by as rejected", async () => {
    const guards = result.tests.filter((t) => t.kind === "guard").map((t) => t.name);
    expect(guards).toEqual([
      "checkout as admin (not in by: customer) is rejected from draft",
      "refund as customer (not in by: admin, system) is rejected from paid",
      "ship as customer (one of by: admin, customer) succeeds from paid",
    ]);
    const file = result.files.find((f) => f.path === "guards.test.ts");
    await expect(file?.content).toMatchFileSnapshot("__golden__/alternatives/guards.test.ts.txt");
  });

  it("keeps the path tests acting as the first listed actor with a fixture", () => {
    const ship = result.tests.filter((t) => t.kind === "path" && t.transition === "ship");
    expect(ship.map((t) => t.name)).toEqual(["ship: paid → shipped (as admin)"]);
  });

  it("explains what it cannot generate: failing one actor's guards, actors without fixture", () => {
    const skipped = result.skipped.filter((f) => f.id.includes(":guards:"));
    expect(skipped.map((f) => [f.id, f.message])).toEqual([
      [
        "not-generated:Order lifecycle:testgen:guards:expire",
        expect.stringContaining("expireOrder takes no actor"),
      ],
      [
        "not-generated:Order lifecycle:testgen:guards:payment_succeeded",
        expect.stringContaining("takes no actor"),
      ],
      [
        "not-generated:Order lifecycle:testgen:guards:refund:system",
        "tsverify test generated no test of `refund` acting as system: system is one of the actors in its by (admin, system) but has no fixture",
      ],
      [
        "not-generated:Order lifecycle:testgen:guards:refund:failing",
        "tsverify test generated no test of `refund` acting as one of its actors but failing that actor's guards (admin: role(admin)): `fixtures.actors` holds one value per actor, which passes its guards. The static check covers these (guard-not-dominating).",
      ],
      [
        "not-generated:Order lifecycle:testgen:guards:ship:failing",
        "tsverify test generated no test of `ship` acting as one of its actors but failing that actor's guards (admin: role(admin); customer: owner): `fixtures.actors` holds one value per actor, which passes its guards. The static check covers these (guard-not-dominating).",
      ],
    ]);
  });
});

describe("B3 (refund race): replay tests", () => {
  const findings = b3.findings as unknown as Finding[];
  const result = generate({
    spec: spec(),
    code: b3.code as unknown as BehaviorModel,
    findings,
    outDir: OUT,
  });
  const replays = result.files.filter((f) => f.path.startsWith("replay-"));

  it("writes a test and a sidecar per counterexample", () => {
    expect(replays.map((f) => f.path)).toEqual([
      "replay-1.test.ts",
      "replay-1.json",
      "replay-2.test.ts",
      "replay-2.json",
    ]);
    expect(result.tests.filter((t) => t.kind === "replay")).toEqual([
      expect.objectContaining({
        file: "replay-1.test.ts",
        finding:
          "implementation-property:Order lifecycle:rule:Refund issued at most once per order",
        property: "rule:Refund issued at most once per order",
        model: "code",
        evaluable: true,
      }),
      expect.objectContaining({
        file: "replay-2.test.ts",
        name: "replay: effect-multiplicity stripe.refund (refund#1 ∥ refund#2)",
        finding: "implementation-property:Order lifecycle:effect-multiplicity:stripe.refund",
        property: "effect-multiplicity",
        transition: "refund",
        model: "code",
        evaluable: true,
      }),
    ]);
  });

  it.each(["replay-1.test.ts", "replay-1.json", "replay-2.test.ts", "replay-2.json"])(
    "%s",
    async (path) => {
      const file = replays.find((f) => f.path === path);
      await expect(file?.content).toMatchFileSnapshot(`__golden__/b3-refund-race/${path}.txt`);
    },
  );

  it("plans with the runtime's default fast-forward on the unchanged trace", () => {
    const test = replays.find((f) => f.path === "replay-2.test.ts")?.content ?? "";
    expect(test).toContain(
      "const plan = planFromTrace(sidecar.trace, mappingFromCode(sidecar.code));",
    );
    const sidecar = JSON.parse(replays.find((f) => f.path === "replay-2.json")?.content ?? "{}");
    expect(sidecar.trace).toEqual(findings[1]?.trace);
    expect(sidecar.$comment).toMatch(/^Generated by tsverify — do not edit\./);
  });

  it("still writes the path, forbidden and guard tests", () => {
    expect(result.files.slice(0, 3).map((f) => f.path)).toEqual([
      "paths.test.ts",
      "forbidden.test.ts",
      "guards.test.ts",
    ]);
  });
});

describe("spec-model counterexample", () => {
  it("is replayed against the code with the same shape", () => {
    const finding: Finding = {
      id: "spec-property:Order lifecycle:rule:Refund issued at most once per order",
      category: "spec-property",
      severity: "error",
      message: "Rule violated.",
      behavior: "Order lifecycle",
      property: "rule:Refund issued at most once per order",
      trace: specTrace as unknown as Trace,
    };
    const result = generate({ spec: spec(), code: clean, findings: [finding], outDir: OUT });
    const test = result.files.find((f) => f.path === "replay-1.test.ts")?.content ?? "";
    expect(test).toContain("Replays its spec-model counterexample against the real code");
    expect(test).toContain('const violated = !((effects["stripe.refunds.create"] ?? 0) <= 1);');
    expect(result.tests.at(-1)).toMatchObject({ kind: "replay", model: "spec", evaluable: true });
  });
});
